let cleanup: () => void;

/** `2026-06-01T0{hour}:00:00.000Z` — every test gets its own hour so a scan
 * driven by one test's `now` never also matches another test's org. */
function nowAtHour(hour: number): Date {
  return new Date(Date.UTC(2026, 5, 1, hour, 0, 0, 0));
}

/** Creates a tenant on `plan` whose digest fires only at `digestHourUtc`, and
 * registers it with the usage rollup so `listOrgIdsForRollup` finds it. */
async function makeTenant(
  slug: string,
  digestHourUtc: number,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const tenant = await createTenant(slug, plan);
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { digestHourUtc },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

/** Subscribes a member to the digest by setting one `digestOnly` preference. */
async function subscribeToDigest(tenant: Tenant): Promise<void> {
  await preferenceRepo.upsertPreference({
    orgId: tenant.org.id,
    userId: tenant.userIds.member,
    kind: "comment_created",
    inApp: false,
    email: false,
    digestOnly: true,
  });
}

async function insertNotificationAt(
  tenant: Tenant,
  at: Date,
  title: string,
): Promise<void> {
  vi.useFakeTimers();
  vi.setSystemTime(at);
  try {
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title,
      body: title,
      href: "/issues/1",
      actorId: null,
      channels: ["email"],
    });
  } finally {
    vi.useRealTimers();
  }
}

/** Pulls a `<td>key</td><td>value</td>` cell out of the generic email table. */
function cell(html: string, key: string): string | null {
  const match = html.match(new RegExp(`<td>${key}</td><td>([^<]*)</td>`));
  return match?.[1] ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("jobs/digest-email-job", () => {
  it("uses the org's configured digest hour to pick the window", async () => {
    const now = nowAtHour(1);
    const tenant = await makeTenant("digest-window", 1);
    await subscribeToDigest(tenant);

    await insertNotificationAt(tenant, new Date(now.getTime() - 12 * 3_600_000), "Recent update");
    await insertNotificationAt(tenant, new Date(now.getTime() - 30 * 3_600_000), "Stale update");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe("1");
    expect(cell(html, "headline")).toBe("Recent update");
  });

  it("skips an org whose digest hour has not arrived", async () => {
    const tenant = await makeTenant("digest-hour-not-yet", 2);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(nowAtHour(2).getTime() - 3_600_000), "Fresh");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    // A run at an hour that does not match the org's configured hour.
    await runDigestEmailJob(nowAtHour(3));

    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("skips an org whose plan does not include digest_email", async () => {
    const now = nowAtHour(4);
    const tenant = await makeTenant("digest-free-plan", 4, "free");
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Fresh");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("sends nothing to a recipient with an empty window", async () => {
    const now = nowAtHour(5);
    const tenant = await makeTenant("digest-empty-window", 5);
    await subscribeToDigest(tenant);
    // Nothing unread inside the window at all.

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    const result = await runDigestEmailJob(now);

    expect(sendSpy).not.toHaveBeenCalled();
    expect(result.processed).toBe(0);
  });

  it("caps the entries at DIGEST_MAX_ENTRIES", async () => {
    const now = nowAtHour(6);
    const tenant = await makeTenant("digest-cap", 6);
    await subscribeToDigest(tenant);

    for (let i = 0; i < DIGEST_MAX_ENTRIES + 5; i += 1) {
      await insertNotificationAt(
        tenant,
        new Date(now.getTime() - (i + 1) * 1_000),
        `Update ${i}`,
      );
    }

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe(String(DIGEST_MAX_ENTRIES));
  });

  it("does not resend a digest for an already-covered window", async () => {
    const now = nowAtHour(7);
    const tenant = await makeTenant("digest-no-resend", 7);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Once");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);
    expect(sendSpy).toHaveBeenCalledTimes(1);

    await runDigestEmailJob(now);
    expect(sendSpy).toHaveBeenCalledTimes(1);
  });

  it("constructs its own actor rather than reading cookies", async () => {
    const now = nowAtHour(8);
    const tenant = await makeTenant("digest-own-actor", 8);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Owns its actor");

    vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    const contextSpy = vi.spyOn(featureFlagService, "buildFlagContext");

    await runDigestEmailJob(now);

    expect(contextSpy).toHaveBeenCalledWith(
      null,
      expect.objectContaining({ id: tenant.org.id }),
    );
  });
});

/**
 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as muteRepo from "@/server/repositories/muted-project-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { toIsoTimestamp } from "@/types/common";
import { notificationResource, projectResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
  projectId?: ProjectId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
const PERSONAL_KINDS: readonly NotificationKind[] = ["issue_assigned", "comment_mention", "issue_overdue"];

async function assertCanReadProject(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(await projectRepo.findProjectById(orgId, projectId), "Project", projectId);
  assertCan(actor, "project:read", projectResource(project));
}

export async function muteProject(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.mute(orgId, actor.userId, projectId);
}

export async function unmuteProject(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.unmute(orgId, actor.userId, projectId);
}

export async function listMutedProjectIds(actor: Actor, orgId: OrgId): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return muteRepo.list(orgId, actor.userId);
}

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const muted = payload.projectId != null && await muteRepo.isMuted(orgId, recipientId, payload.projectId);
    if (muted && !PERSONAL_KINDS.includes(kind)) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const resolved = resolveChannels(preference, flags);
    const channels = muted ? resolved.filter((channel) => channel !== "email") : resolved;
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      projectId: payload.projectId ?? null,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
      projectId: payload.projectId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
      projectId: payload.projectId,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
      projectId: issue?.projectId ?? null,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
          projectId: issue?.projectId ?? null,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });
}

registerFanOut();

/**
 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 *
 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
import { sendEmail } from "@/server/services/email-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Organization } from "@/types/organization";

const ORG_BATCH = 50;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("digest-email-job");

/**
 * One pass per scheduler tick. Each org is only processed during the UTC hour
 * it configured, so a tick that runs every few minutes still sends exactly one
 * digest per day per recipient.
 */
export async function runDigestEmailJob(now: Date): Promise<JobResult> {
  return runJob("digest-email", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || !shouldRunForOrg(org, now)) continue;

      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;

      const windowEnd = toIsoTimestamp(now);
      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));

      for (const recipientId of await listDigestRecipients(orgId)) {
        try {
          const bundle = await buildDigest(
            orgId,
            recipientId,
            windowStart,
            windowEnd,
          );
          if (!bundle) continue;

          const recipient = await userRepo.findUserById(recipientId);
          if (!recipient) continue;

          const rendered = await renderDigest(bundle, recipient);
          await sendEmail({ to: recipient.email, ...rendered });

          // Once digested, these notifications are no longer "unread" — this
          // is what keeps a later run inside the same window from sending
          // the same digest twice.
          for (const entry of bundle.entries) {
            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
          }

          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("digest failed", {
            orgId,
            recipientId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}

/**
 * True during the org's configured digest hour. Exported because the schedule
 * decision is worth testing on its own, without a database.
 */
export function shouldRunForOrg(org: Organization, now: Date): boolean {
  if (org.archivedAt !== null) return false;
  return now.getUTCHours() === org.settings.digestHourUtc;
}
/**
 * Applies the drizzle-kit migrations in ./drizzle to the SQLite file. Run via `pnpm db:migrate`.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import Database from "better-sqlite3";

const DEFAULT_DB_PATH = "./data/taskflow.db";
const MIGRATIONS_DIR = "./drizzle";

/**
 * Statements that bring an empty database up to the current schema.
 *
